import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class StdTypeResolverBuilder_typeProperty_TriageGen2Test {

    @Mock
    private TypeIdResolver mockIdResolver;





    @Test
    public void testTypeProperty_WithEmptyString() {
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder();
        builder.init(JsonTypeInfo.Id.NAME, mockIdResolver);

        String expectedDefault = JsonTypeInfo.Id.NAME.getDefaultPropertyName();

        builder.typeProperty("");

        assertEquals(expectedDefault, builder.getTypeProperty());
    }
}
